    {
      "code": "MEASURE_RELIABILITY",
      "text": "Play-type definitions in the graph database may not be consistent across teams or seasons; slight reclassifications could alter distance ranks."
    },
    {
      "code": "MECHANICAL_FLOOR",
      "text": "If the absent player's primary type is a rare action (e.g. post-up), the pool of teammates initiating that type is tiny, making 'gain' a binary and rank unstable."
    },
    {
      "code": "MULTIPLE_TESTING",
      "text": "Comparisons across several distance metrics and primary-type thresholds inevitably inflate false-positive risk unless pre-registered."
    }
  ],
  "predicted_outcome": {
    "supported": 0.10,
    "rejected": 0.15,
    "untestable": 0.35,
    "artifact": 0.20,
    "uncertain": 0.20
  },
  "decision": "do_not_proceed",
  "design": {
    "estimand": "Average within-spell rank correlation between pre-absence initiation-profile distance and gain in the absent player's primary play types (gain defined as change in per-possession share of those types, adjusted for minutes). The smallest-distance teammate is expected to show the largest gain.",
